// The update log (updates.ts) in every language: updates 56 to 60. See updates.ts in this folder.
import type { Row } from "./table.ts";

export const UPDATES11: Readonly<Record<string, Row>> = {
  "The dungeon update: three new dungeons, ten new creatures, coffers everywhere": ["ダンジョンアップデート：新ダンジョン3つ、新しい生き物10種、どこにでも宝箱", "던전 업데이트: 새 던전 셋, 새 생물 열, 곳곳의 보물상자", "地下城更新：三座新地下城、十种新生物、宝箱遍地", "地下城更新：三座新地下城、十種新生物、寶箱遍地", "Bản cập nhật hầm ngục: ba hầm ngục mới, mười sinh vật mới, rương báu khắp nơi", "Pembaruan ruang bawah tanah: tiga ruang baru, sepuluh makhluk baru, peti di mana-mana", "อัปเดตดันเจี้ยน: ดันเจี้ยนใหม่สามแห่ง สิ่งมีชีวิตใหม่สิบชนิด หีบสมบัติทุกที่", "Zindan güncellemesi: üç yeni zindan, on yeni yaratık, her yerde sandıklar", "La actualización de mazmorras: tres mazmorras nuevas, diez criaturas nuevas y cofres por todas partes", "A atualização das masmorras: três masmorras novas, dez criaturas novas e baús por toda parte", "Обновление подземелий: три новых подземелья, десять новых существ и сундуки повсюду", "Оновлення підземель: три нові підземелля, десять нових істот і скрині всюди"],
  "Three new dungeons. The Deepglass Caverns, through a crevice on Glass Lake's east shore: cave bats, glass crabs and the Crystal Golem behind a crystal door (combat 20 to 55). The Drowned Archive, under a trapdoor in the Quillhaven library: drowned scholars who cast, ink wraiths that drain your faith, and the Archivist Below in the sealed reading room, mending himself as you fight (35 to 75). The Howling Vault, under the ring of standing stones in The Wilds: grave moths, vault archers that shoot from across the gallery, vault knights, and the Howling King, who enrages when he's hurt (45 to 96).": ["新しいダンジョンが3つ。グラス湖の東岸の裂け目から入る Deepglass Caverns：洞窟コウモリ、ガラスガニ、そして水晶の扉の奥の Crystal Golem（戦闘20〜55）。クイルヘイヴンの図書館の落とし戸の下にある Drowned Archive：呪文を唱える溺れた学者、信仰を吸うインクの亡霊、封印された閲覧室にいて戦いながら自分を修復する Archivist Below（35〜75）。荒野の立石の輪の下にある Howling Vault：墓蛾、回廊の向こうから射る宝物庫の射手、宝物庫の騎士、そして傷つくと激昂する Howling King（45〜96）。", "새 던전 셋. 유리 호수 동쪽 기슭의 틈으로 들어가는 Deepglass Caverns: 동굴 박쥐, 유리게, 그리고 수정 문 너머의 Crystal Golem(전투 20~55). 퀼헤이븐 도서관 뚜껑문 아래의 Drowned Archive: 주문을 쓰는 물에 잠긴 학자, 신앙을 빨아들이는 먹물 망령, 봉인된 열람실에서 싸우는 동안 스스로를 고치는 Archivist Below(35~75). 황야의 선돌 고리 아래 Howling Vault: 무덤 나방, 회랑 건너에서 쏘는 금고 궁수, 금고 기사, 그리고 다치면 격분하는 Howling King(45~96).", "三座新地下城。从玻璃湖东岸的裂缝进入的 Deepglass Caverns：洞穴蝙蝠、玻璃蟹，以及水晶门后的 Crystal Golem（战斗 20 到 55）。羽港图书馆活板门下的 Drowned Archive：会施法的溺亡学者、吸取信仰的墨魂，以及在密封阅览室里、边打边自我修复的 Archivist Below（35 到 75）。荒野立石圈下的 Howling Vault：墓蛾、从回廊对面射击的宝库弓手、宝库骑士，以及受伤就会暴怒的 Howling King（45 到 96）。", "三座新地下城。從玻璃湖東岸的裂縫進入的 Deepglass Caverns：洞穴蝙蝠、玻璃蟹，以及水晶門後的 Crystal Golem（戰鬥 20 到 55）。羽港圖書館活板門下的 Drowned Archive：會施法的溺亡學者、吸取信仰的墨魂，以及在密封閱覽室裡、邊打邊自我修復的 Archivist Below（35 到 75）。荒野立石圈下的 Howling Vault：墓蛾、從迴廊對面射擊的寶庫弓手、寶庫騎士，以及受傷就會暴怒的 Howling King（45 到 96）。", "Ba hầm ngục mới. Deepglass Caverns, qua một khe nứt ở bờ đông Hồ Kính: dơi hang, cua thủy tinh và Crystal Golem sau một cánh cửa pha lê (chiến đấu 20 đến 55). Drowned Archive, dưới cửa sập trong thư viện Quillhaven: học giả chết đuối biết phép, bóng ma mực hút đức tin của bạn, và Archivist Below trong phòng đọc niêm phong, tự hồi phục khi bạn đánh (35 đến 75). Howling Vault, dưới vòng đá dựng ở Vùng Hoang dã: bướm đêm mộ, cung thủ hầm bắn từ bên kia hành lang, hiệp sĩ hầm, và Howling King, nổi điên khi bị thương (45 đến 96).", "Tiga ruang bawah tanah baru. Deepglass Caverns, lewat celah di pantai timur Danau Kaca: kelelawar gua, kepiting kaca, dan Crystal Golem di balik pintu kristal (tempur 20 hingga 55). Drowned Archive, di bawah pintu kolong di perpustakaan Quillhaven: cendekiawan tenggelam yang merapal, arwah tinta yang menguras imanmu, dan Archivist Below di ruang baca tersegel, memulihkan diri saat kau bertarung (35 hingga 75). Howling Vault, di bawah lingkaran batu tegak di The Wilds: ngengat kubur, pemanah ruang besi yang menembak dari seberang galeri, ksatria ruang besi, dan Howling King, yang mengamuk saat terluka (45 hingga 96).", "ดันเจี้ยนใหม่สามแห่ง Deepglass Caverns ผ่านรอยแยกที่ฝั่งตะวันออกของทะเลสาบแก้ว: ค้างคาวถ้ำ ปูแก้ว และ Crystal Golem หลังประตูคริสตัล (ต่อสู้ 20 ถึง 55) Drowned Archive ใต้ประตูกลในห้องสมุดควิลเฮเวน: นักปราชญ์จมน้ำที่ร่ายเวท ปีศาจหมึกที่ดูดศรัทธา และ Archivist Below ในห้องอ่านหนังสือที่ผนึกไว้ ซึ่งซ่อมตัวเองขณะต่อสู้ (35 ถึง 75) Howling Vault ใต้วงหินตั้งในป่าเถื่อน: ผีเสื้อกลางคืนหลุมศพ นักธนูห้องนิรภัยที่ยิงจากอีกฟากระเบียง อัศวินห้องนิรภัย และ Howling King ที่คลั่งเมื่อบาดเจ็บ (45 ถึง 96)", "Üç yeni zindan. Cam Göl'ün doğu kıyısındaki bir yarıktan Deepglass Caverns: mağara yarasaları, cam yengeçler ve kristal bir kapının ardındaki Crystal Golem (savaş 20 ile 55). Quillhaven kütüphanesindeki bir kapağın altında Drowned Archive: büyü yapan boğulmuş bilginler, inancını emen mürekkep hayaletleri ve mühürlü okuma odasında sen dövüşürken kendini onaran Archivist Below (35 ile 75). Yabanlar'daki dikili taş halkasının altında Howling Vault: mezar güveleri, galerinin öbür ucundan ateş eden kasa okçuları, kasa şövalyeleri ve yaralandığında öfkelenen Howling King (45 ile 96).", "Tres mazmorras nuevas. Las Deepglass Caverns, por una grieta en la orilla este del Lago de Cristal: murciélagos, cangrejos de cristal y el Crystal Golem tras una puerta de cristal (combate de 20 a 55). El Drowned Archive, bajo una trampilla en la biblioteca de Quillhaven: eruditos ahogados que lanzan hechizos, espectros de tinta que te drenan la fe y el Archivist Below en la sala de lectura sellada, que se repara mientras luchas (de 35 a 75). La Howling Vault, bajo el círculo de piedras de Las Tierras Salvajes: polillas de tumba, arqueros que disparan desde el otro lado de la galería, caballeros de la cámara y el Howling King, que se enfurece cuando lo hieren (de 45 a 96).", "Três masmorras novas. As Deepglass Caverns, por uma fenda na margem leste do Lago de Vidro: morcegos, caranguejos de vidro e o Crystal Golem atrás de uma porta de cristal (combate de 20 a 55). O Drowned Archive, sob um alçapão na biblioteca de Quillhaven: eruditos afogados que lançam feitiços, espectros de tinta que drenam sua fé e o Archivist Below na sala de leitura selada, se consertando enquanto você luta (35 a 75). A Howling Vault, sob o círculo de pedras erguidas nas Terras Selvagens: mariposas de túmulo, arqueiros do cofre que atiram do outro lado da galeria, cavaleiros do cofre e o Howling King, que se enfurece quando ferido (45 a 96).", "Три новых подземелья. Deepglass Caverns — через расщелину на восточном берегу Стеклянного озера: пещерные летучие мыши, стеклянные крабы и Crystal Golem за хрустальной дверью (бой 20–55). Drowned Archive — под люком в библиотеке Квиллхейвена: утонувшие учёные, творящие заклинания, чернильные призраки, высасывающие веру, и Archivist Below в запечатанном читальном зале, чинящий себя во время боя (35–75). Howling Vault — под кругом стоячих камней в Дичи: могильные мотыльки, лучники хранилища, стреляющие через галерею, рыцари хранилища и Howling King, впадающий в ярость от ран (45–96).", "Три нові підземелля. Deepglass Caverns — через щілину на східному березі Скляного озера: печерні кажани, скляні краби й Crystal Golem за кришталевими дверима (бій 20–55). Drowned Archive — під люком у бібліотеці Квіллгейвена: утоплені учені, що творять заклинання, чорнильні примари, що висмоктують віру, і Archivist Below у запечатаній читальній залі, що лагодить себе під час бою (35–75). Howling Vault — під колом стоячих каменів у Дикині: могильні метелики, лучники сховища, що стріляють через галерею, лицарі сховища й Howling King, що шаленіє від ран (45–96)."],
  "Locked doors and keys: each new dungeon's boss waits behind a door that takes a key, dropped by its creatures, found in its coffers, or given by the quest. A key turns once and breaks.": ["鍵のかかった扉と鍵：新ダンジョンのボスはそれぞれ鍵が必要な扉の奥にいます。鍵はそこの生き物が落とすか、宝箱で見つかるか、クエストでもらえます。鍵は一度回すと壊れます。", "잠긴 문과 열쇠: 새 던전마다 보스가 열쇠가 필요한 문 뒤에서 기다립니다. 열쇠는 그곳 생물이 떨어뜨리거나, 보물상자에서 나오거나, 퀘스트로 받습니다. 열쇠는 한 번 돌리면 부러집니다.", "上锁的门与钥匙：每座新地下城的首领都在一扇需要钥匙的门后，钥匙由那里的生物掉落、在宝箱里找到，或由任务给予。钥匙转一次就会断。", "上鎖的門與鑰匙：每座新地下城的首領都在一扇需要鑰匙的門後，鑰匙由那裡的生物掉落、在寶箱裡找到，或由任務給予。鑰匙轉一次就會斷。", "Cửa khóa và chìa khóa: trùm của mỗi hầm ngục mới đợi sau một cánh cửa cần chìa, do sinh vật ở đó rơi ra, tìm thấy trong rương, hoặc được nhiệm vụ trao. Chìa khóa xoay một lần là gãy.", "Pintu terkunci dan kunci: bos setiap ruang bawah tanah baru menunggu di balik pintu yang butuh kunci, dijatuhkan makhluknya, ditemukan di petinya, atau diberikan oleh misi. Kunci berputar sekali lalu patah.", "ประตูล็อกและกุญแจ: บอสของดันเจี้ยนใหม่แต่ละแห่งรออยู่หลังประตูที่ต้องใช้กุญแจ ซึ่งสิ่งมีชีวิตที่นั่นดรอป เจอในหีบ หรือได้จากเควสต์ กุญแจไขได้ครั้งเดียวแล้วหัก", "Kilitli kapılar ve anahtarlar: her yeni zindanın patronu bir anahtar isteyen bir kapının ardında bekler; anahtarı oradaki yaratıklar düşürür, sandıklarında bulunur ya da görev verir. Bir anahtar bir kez döner ve kırılır.", "Puertas cerradas y llaves: el jefe de cada mazmorra nueva espera tras una puerta que pide una llave, que sueltan sus criaturas, aparece en sus cofres o da la misión. Una llave gira una vez y se rompe.", "Portas trancadas e chaves: o chefe de cada masmorra nova espera atrás de uma porta que pede uma chave, solta pelas criaturas, achada nos baús ou dada pela missão. Uma chave gira uma vez e quebra.", "Запертые двери и ключи: босс каждого нового подземелья ждёт за дверью, для которой нужен ключ — его роняют существа, находят в сундуках или дают по квесту. Ключ поворачивается один раз и ломается.", "Замкнені двері й ключі: бос кожного нового підземелля чекає за дверима, для яких потрібен ключ — його впускають істоти, знаходять у скринях або дають за квестом. Ключ повертається один раз і ламається."],
  "Coffers in every dungeon, old and new: right-click Search for loot that belongs down there (coins, bones, sigils, ore, gems, pages, grave dust), sometimes the dungeon's key, and a slim chance at something rare (lamps of insight, glimmer and rarite armour, the new bosses' own gear). A coffer searched is empty for fifteen minutes; the named hoards behind the bosses are richer.": ["新旧すべてのダンジョンに宝箱：右クリックで「探す」と、その場所らしい戦利品（コイン、骨、シジル、鉱石、宝石、紙片、墓の塵）、ときにはダンジョンの鍵、そしてまれに珍しいもの（洞察のランプ、グリマーやレアライトの鎧、新ボスの装備）。探した宝箱は15分間空になります。ボスの奥にある名のある財宝はさらに豪華です。", "새 던전과 옛 던전 모두에 보물상자: 우클릭으로 '뒤지기'를 하면 그곳에 어울리는 전리품(코인, 뼈, 인장, 광석, 보석, 종이, 무덤 먼지), 가끔 던전 열쇠, 그리고 희귀한 것(통찰의 등불, 글리머와 레어라이트 갑옷, 새 보스의 장비)이 나올 작은 확률. 뒤진 상자는 15분간 비고, 보스 뒤의 이름 있는 보물은 더 풍성합니다.", "新旧所有地下城都有宝箱：右键搜索可获得属于那里的战利品（金币、骨头、印记、矿石、宝石、书页、墓尘），有时是地下城的钥匙，还有很小的几率得到稀有物品（洞察之灯、微光和稀晶盔甲、新首领的专属装备）。搜过的宝箱十五分钟内是空的；首领身后有名字的宝藏更丰厚。", "新舊所有地下城都有寶箱：右鍵搜索可獲得屬於那裡的戰利品（金幣、骨頭、印記、礦石、寶石、書頁、墓塵），有時是地下城的鑰匙，還有很小的機率得到稀有物品（洞察之燈、微光和稀晶盔甲、新首領的專屬裝備）。搜過的寶箱十五分鐘內是空的；首領身後有名字的寶藏更豐厚。", "Rương báu trong mọi hầm ngục, cũ và mới: nhấp chuột phải Tìm kiếm để nhận chiến lợi phẩm thuộc về nơi đó (xu, xương, ấn, quặng, đá quý, trang giấy, bụi mộ), đôi khi là chìa khóa của hầm ngục, và một cơ hội nhỏ nhận thứ hiếm (đèn minh triết, giáp ánh kim và rarit, trang bị riêng của các trùm mới). Rương đã tìm sẽ trống trong mười lăm phút; kho báu có tên sau các trùm phong phú hơn.", "Peti di setiap ruang bawah tanah, lama dan baru: klik kanan Cari untuk jarahan khas tempat itu (koin, tulang, sigil, bijih, permata, halaman, debu kubur), kadang kunci ruang bawah tanah, dan peluang tipis untuk sesuatu yang langka (lampu wawasan, zirah kemilau dan rarit, perlengkapan khas bos baru). Peti yang sudah dicari kosong selama lima belas menit; timbunan bernama di balik bos lebih kaya.", "หีบสมบัติในทุกดันเจี้ยน ทั้งเก่าและใหม่: คลิกขวาค้นเพื่อหาของที่เข้ากับที่นั่น (เหรียญ กระดูก ผนึก แร่ อัญมณี หน้ากระดาษ ฝุ่นหลุมศพ) บางครั้งเป็นกุญแจดันเจี้ยน และโอกาสน้อยๆ ที่จะได้ของหายาก (ตะเกียงแห่งปัญญา เกราะประกายแสงและแรไรต์ อุปกรณ์ของบอสใหม่) หีบที่ค้นแล้วจะว่างสิบห้านาที กองสมบัติมีชื่อหลังบอสรวยกว่า", "Eski ve yeni her zindanda sandıklar: oraya ait ganimet için sağ tıkla Ara (para, kemik, mühür, cevher, mücevher, sayfa, mezar tozu), bazen zindanın anahtarı ve nadir bir şey için ufak bir şans (içgörü lambaları, parıltı ve rarit zırh, yeni patronların kendi teçhizatı). Aranan bir sandık on beş dakika boş kalır; patronların ardındaki adlı hazineler daha zengin.", "Cofres en todas las mazmorras, antiguas y nuevas: clic derecho en Buscar para botín propio de allí abajo (monedas, huesos, sigilos, mineral, gemas, páginas, polvo de tumba), a veces la llave de la mazmorra y una pequeña posibilidad de algo raro (lámparas de la perspicacia, armadura de destello y rarita, el equipo de los nuevos jefes). Un cofre registrado queda vacío quince minutos; los tesoros con nombre tras los jefes son más ricos.", "Baús em toda masmorra, velha e nova: clique direito em Revistar para saque de lá de baixo (moedas, ossos, sigilos, minério, gemas, páginas, pó de túmulo), às vezes a chave da masmorra e uma chance pequena de algo raro (lâmpadas da perspicácia, armadura de lampejo e rarita, o equipamento dos chefes novos). Um baú revistado fica vazio por quinze minutos; os tesouros com nome atrás dos chefes são mais ricos.", "Сундуки во всех подземельях, старых и новых: правый клик «Обыскать» — добыча, подходящая месту (монеты, кости, печати, руда, самоцветы, страницы, могильная пыль), иногда ключ от подземелья и небольшой шанс на редкость (лампы прозрения, доспехи из мерцалита и рарита, снаряжение новых боссов). Обысканный сундук пуст пятнадцать минут; именные клады за боссами богаче.", "Скрині в усіх підземеллях, старих і нових: правий клік «Обшукати» — здобич, що пасує місцю (монети, кістки, печатки, руда, самоцвіти, сторінки, могильний пил), іноді ключ від підземелля й невеликий шанс на рідкість (лампи прозріння, обладунки з мерехтиту й рариту, спорядження нових босів). Обшукана скриня порожня п'ятнадцять хвилин; іменні скарби за босами багатші."],
  "Three quests: The Heart of the Lake (the Old fisher on the pier, combat 30), The Drowned Archive (Perrin Quill after The Missing Folio, Magic 40) and What the Stones Keep (Huntmaster Fenn after Tracks in the Tallgrass, combat 70). Six Slayer tasks for the new creatures.": ["クエストが3つ：「湖の心臓」（桟橋の年寄りの漁師、戦闘30）、「沈んだ書庫」（「消えた写本」のあとの Perrin Quill、魔法40）、「石が守るもの」（「背高草の足跡」のあとの狩猟頭フェン、戦闘70）。新しい生き物の討伐任務が6つ。", "퀘스트 셋: '호수의 심장'(부두의 늙은 어부, 전투 30), '가라앉은 서고'('사라진 필사본' 이후 Perrin Quill, 마법 40), '돌이 지키는 것'('키 큰 풀숲의 발자국' 이후 사냥대장 펜, 전투 70). 새 생물을 위한 토벌 임무 여섯.", "三个任务：「湖之心」（码头上的老渔夫，战斗 30）、「沉没的档案馆」（完成「失踪的手稿」后找 Perrin Quill，魔法 40）和「石头守护之物」（完成「高草中的足迹」后找猎头芬恩，战斗 70）。新生物有六个猎杀任务。", "三個任務：「湖之心」（碼頭上的老漁夫，戰鬥 30）、「沉沒的檔案館」（完成「失蹤的手稿」後找 Perrin Quill，魔法 40）和「石頭守護之物」（完成「高草中的足跡」後找獵頭芬恩，戰鬥 70）。新生物有六個獵殺任務。", "Ba nhiệm vụ: Trái tim của hồ (lão đánh cá trên cầu tàu, chiến đấu 30), Kho lưu trữ chìm (Perrin Quill sau Bản thảo mất tích, Phép thuật 40) và Điều đá canh giữ (Thủ lĩnh săn Fenn sau Dấu chân trong cỏ cao, chiến đấu 70). Sáu nhiệm vụ Diệt quái cho các sinh vật mới.", "Tiga misi: Jantung Danau (nelayan tua di dermaga, tempur 30), Arsip yang Tenggelam (Perrin Quill setelah Naskah yang Hilang, Sihir 40), dan Yang Dijaga Batu (Kepala Pemburu Fenn setelah Jejak di Rumput Tinggi, tempur 70). Enam tugas Pembasmi untuk makhluk baru.", "เควสต์สามเควสต์: หัวใจแห่งทะเลสาบ (ชาวประมงชราบนท่าเรือ ต่อสู้ 30) หอจดหมายเหตุใต้น้ำ (Perrin Quill หลังต้นฉบับที่หายไป เวทมนตร์ 40) และสิ่งที่หินปกปักษ์ (หัวหน้านักล่าเฟนน์หลังรอยเท้าในหญ้าสูง ต่อสู้ 70) ภารกิจล่าอสูรหกภารกิจสำหรับสิ่งมีชีวิตใหม่", "Üç görev: Gölün Kalbi (iskeledeki yaşlı balıkçı, savaş 30), Batık Arşiv (Kayıp Yazma'dan sonra Perrin Quill, Büyü 40) ve Taşların Sakladığı (Uzun Otlardaki İzler'den sonra Av Ustası Fenn, savaş 70). Yeni yaratıklar için altı Avcı görevi.", "Tres misiones: El corazón del lago (el viejo pescador del muelle, combate 30), El archivo ahogado (Perrin Quill tras El folio perdido, Magia 40) y Lo que guardan las piedras (el maestro cazador Fenn tras Huellas en la hierba alta, combate 70). Seis tareas de Cazador para las criaturas nuevas.", "Três missões: O Coração do Lago (o velho pescador no píer, combate 30), O Arquivo Afogado (Perrin Quill depois de O Fólio Desaparecido, Magia 40) e O que as Pedras Guardam (o mestre caçador Fenn depois de Rastros no Capim Alto, combate 70). Seis tarefas de Caçador para as criaturas novas.", "Три квеста: «Сердце озера» (старый рыбак на пирсе, бой 30), «Затонувший архив» (Perrin Quill после «Пропавшего фолианта», Магия 40) и «Что хранят камни» (старший охотник Фенн после «Следов в высокой траве», бой 70). Шесть заданий Истребления на новых существ.", "Три квести: «Серце озера» (старий рибалка на пірсі, бій 30), «Затоплений архів» (Perrin Quill після «Зниклого фоліанта», Магія 40) і «Що бережуть камені» (старший мисливець Фенн після «Слідів у високій траві», бій 70). Шість завдань Винищувача на нових істот."],
  "New gear from the bosses: the Glassbrand sabre, Crystal shield and Lakeglass charm; the Inkbound tome (off-hand, Magic 55), Archivist's cowl and Drowned staff; the Vaultsteel blade, Vault helm and plate, and the Howling cape.": ["ボスからの新装備：Glassbrand sabre、水晶の盾、湖ガラスのお守り。インク綴じの書（副手、魔法55）、書庫番の頭巾、溺れた杖。宝物庫鋼の刃、宝物庫の兜と鎧、遠吠えのマント。", "보스의 새 장비: Glassbrand sabre, 수정 방패, 호수유리 부적; 잉크로 묶인 고서(보조손, 마법 55), 기록관의 두건, 익사한 지팡이; 금고강철 칼날, 금고 투구와 판금, 울부짖는 망토.", "首领的新装备：Glassbrand sabre、水晶盾和湖玻璃护符；墨封典籍（副手，魔法 55）、档案员兜帽和溺亡法杖；宝库钢刃、宝库头盔和板甲，以及嚎叫披风。", "首領的新裝備：Glassbrand sabre、水晶盾和湖玻璃護符；墨封典籍（副手，魔法 55）、檔案員兜帽和溺亡法杖；寶庫鋼刃、寶庫頭盔和板甲，以及嚎叫披風。", "Trang bị mới từ các trùm: Glassbrand sabre, Khiên pha lê và Bùa kính hồ; Sách phong ấn mực (tay phụ, Phép thuật 55), Mũ trùm người giữ thư khố và Gậy chết đuối; Lưỡi kiếm thép hầm, Mũ giáp hầm và giáp tấm, và Áo choàng hú gào.", "Perlengkapan baru dari bos: Glassbrand sabre, Perisai kristal, dan Jimat kaca danau; Kitab berjilid tinta (tangan kedua, Sihir 55), Tudung arsiparis, dan Tongkat tenggelam; Bilah baja ruang besi, Helm ruang besi dan zirah pelatnya, dan Mantel lolongan.", "อุปกรณ์ใหม่จากบอส: Glassbrand sabre โล่คริสตัล และเครื่องรางแก้วทะเลสาบ ตำราผนึกหมึก (มือรอง เวทมนตร์ 55) ผ้าคลุมหัวบรรณารักษ์ และคทาจมน้ำ ดาบเหล็กห้องนิรภัย หมวกเกราะและเกราะแผ่นห้องนิรภัย และผ้าคลุมเสียงหอน", "Patronlardan yeni teçhizat: Glassbrand sabre, Kristal kalkan ve Göl camı muskası; Mürekkep ciltli kitap (yardımcı el, Büyü 55), Arşivci başlığı ve Boğulmuş asa; Kasa çeliği kılıç, Kasa miğferi ve zırhı ve Uluyan pelerin.", "Equipo nuevo de los jefes: el Glassbrand sabre, el Escudo de cristal y el Amuleto de vidrio de lago; el Tomo atado en tinta (mano secundaria, Magia 55), la Capucha del archivero y el Bastón ahogado; la Hoja de acero de cámara, el Yelmo y la armadura de la cámara, y la Capa aullante.", "Equipamento novo dos chefes: o Glassbrand sabre, o Escudo de cristal e o Amuleto de vidro do lago; o Tomo selado a tinta (mão secundária, Magia 55), o Capuz do arquivista e o Cajado afogado; a Lâmina de aço do cofre, o Elmo e a armadura do cofre, e a Capa uivante.", "Новое снаряжение с боссов: Glassbrand sabre, хрустальный щит и оберег из озёрного стекла; том в чернильном переплёте (вторая рука, Магия 55), клобук архивариуса и утопленный посох; клинок из стали хранилища, шлем и латы хранилища и воющий плащ.", "Нове спорядження з босів: Glassbrand sabre, кришталевий щит і оберіг з озерного скла; том у чорнильній палітурці (друга рука, Магія 55), каптур архіваріуса й утоплений посох; клинок зі сталі сховища, шолом і лати сховища та виючий плащ."],
  "Three new tracks on the jukebox, one for each dungeon.": ["ジュークボックスに新曲が3曲、ダンジョンごとに1曲。", "주크박스에 새 곡 셋, 던전마다 하나씩.", "点唱机新增三首曲子，每座地下城一首。", "點唱機新增三首曲子，每座地下城一首。", "Ba bản nhạc mới trong máy hát, mỗi hầm ngục một bản.", "Tiga lagu baru di jukebox, satu untuk setiap ruang bawah tanah.", "เพลงใหม่สามเพลงในตู้เพลง ดันเจี้ยนละหนึ่งเพลง", "Müzik kutusunda üç yeni parça, her zindan için bir tane.", "Tres pistas nuevas en la gramola, una por mazmorra.", "Três faixas novas na jukebox, uma para cada masmorra.", "Три новых трека в музыкальном автомате — по одному на подземелье.", "Три нові треки в музичному автоматі — по одному на підземелля."],
  "Seen from behind with no cape on, a shield is painted over your body and your pack now, in front, where it used to sink in. The fellowship page is more compact: the emblems and banners scroll in their own rows and the recruiting card is smaller, so it fits the screen.": ["マントなしで後ろから見ると、盾は以前のようにめり込まず、体と荷物の手前に描かれるようになりました。団のページはコンパクトに：紋章と旗はそれぞれの列でスクロールし、勧誘カードは小さくなって画面に収まります。", "망토 없이 뒤에서 보면 방패가 예전처럼 파묻히지 않고 몸과 가방 앞에 그려집니다. 길드 페이지가 더 간결해졌습니다: 문장과 깃발은 각자의 줄에서 스크롤되고, 모집 카드는 작아져 화면에 맞습니다.", "不穿披风从背后看时，盾牌现在画在身体和背包的前面，而不是像以前那样陷进去。公会页面更紧凑了：徽章和旗帜在各自的行中滚动，招募卡片更小，能放进屏幕。", "不穿披風從背後看時，盾牌現在畫在身體和背包的前面，而不是像以前那樣陷進去。公會頁面更緊湊了：徽章和旗幟在各自的列中捲動，招募卡片更小，能放進螢幕。", "Nhìn từ phía sau khi không mặc áo choàng, khiên giờ được vẽ đè lên thân và túi đồ, ở phía trước, chỗ trước đây nó bị lún vào. Trang bang hội gọn hơn: huy hiệu và cờ cuộn trong hàng riêng và thẻ chiêu mộ nhỏ hơn, nên vừa màn hình.", "Dilihat dari belakang tanpa jubah, perisai kini dilukis di atas tubuh dan tasmu, di depan, di tempat dulu ia tenggelam. Halaman persekutuan lebih ringkas: lambang dan spanduk bergulir di barisnya sendiri dan kartu perekrutan lebih kecil, jadi muat di layar.", "มองจากด้านหลังโดยไม่ใส่ผ้าคลุม โล่ตอนนี้วาดทับลำตัวและกระเป๋าไว้ข้างหน้า ตรงที่เคยจมลงไป หน้ากิลด์กระชับขึ้น: ตราและธงเลื่อนในแถวของตัวเอง และการ์ดรับสมัครเล็กลง พอดีจอ", "Pelerinsiz arkadan bakınca kalkan artık eskiden gömüldüğü yerde değil, bedeninin ve çantanın önünde çiziliyor. Kardeşlik sayfası daha derli toplu: amblemler ve sancaklar kendi satırlarında kayıyor ve üye toplama kartı ekrana sığacak kadar küçük.", "Visto desde detrás sin capa, el escudo se pinta ahora sobre tu cuerpo y tu mochila, delante, donde antes se hundía. La página de la hermandad es más compacta: los emblemas y estandartes se desplazan en sus propias filas y la tarjeta de reclutamiento es más pequeña, así que cabe en pantalla.", "Visto de trás sem capa, o escudo agora é pintado por cima do corpo e da mochila, na frente, onde antes afundava. A página da irmandade está mais compacta: os emblemas e estandartes rolam em linhas próprias e o cartão de recrutamento é menor, então cabe na tela.", "Если смотреть сзади без плаща, щит теперь рисуется поверх тела и сумки, впереди, а не проваливается, как раньше. Страница братства стала компактнее: эмблемы и знамёна листаются в своих рядах, а карточка набора меньше и помещается на экран.", "Якщо дивитися ззаду без плаща, щит тепер малюється поверх тіла й сумки, попереду, а не провалюється, як раніше. Сторінка братства стала компактнішою: емблеми й знамена гортаються у своїх рядах, а картка набору менша й уміщується на екран."],
  "Joining a fellowship a fellow invited you to costs 500 coins now (founding one is still the registrar's 5,000). And the Greyhorn's snow caps above Highcairn are bare grey rock: they sat oddly over the slopes.": ["仲間に招待された団への加入は500コインになりました（設立は引き続き登録所で5,000）。また、ハイケアンの上のグレイホーンの雪冠はむき出しの灰色の岩に：斜面の上で不自然に見えていたためです。", "동료가 초대한 길드에 가입하는 데 이제 500코인이 듭니다(창설은 여전히 등록소에서 5,000). 그리고 하이케언 위 그레이혼의 만년설은 맨 회색 바위가 되었습니다: 비탈 위에 어색하게 얹혀 있었거든요.", "加入同伴邀请你的公会现在只需 500 金币（创建公会仍是登记处的 5,000）。另外，高冢上方灰角山的雪冠改成了裸露的灰岩：它们之前在山坡上显得很怪。", "加入同伴邀請你的公會現在只需 500 金幣（建立公會仍是登記處的 5,000）。另外，高塚上方灰角山的雪冠改成了裸露的灰岩：它們之前在山坡上顯得很怪。", "Gia nhập bang hội mà đồng đội mời giờ tốn 500 xu (lập bang vẫn là 5.000 của người đăng ký). Và mũ tuyết của Greyhorn phía trên Highcairn giờ là đá xám trơ trụi: trước đây chúng nằm lạ lùng trên sườn núi.", "Bergabung dengan persekutuan yang diundang rekan kini seharga 500 koin (mendirikannya tetap 5.000 di pendaftar). Dan puncak salju Greyhorn di atas Highcairn kini batu kelabu gundul: dulu tampak aneh di atas lereng.", "การเข้ากิลด์ที่พวกพ้องเชิญตอนนี้ใช้ 500 เหรียญ (การก่อตั้งยังคง 5,000 ที่นายทะเบียน) และยอดหิมะของเกรย์ฮอร์นเหนือไฮแคร์นเป็นหินสีเทาเปลือย: ก่อนหน้านี้มันดูแปลกบนลาดเขา", "Bir dostun seni davet ettiği bir kardeşliğe katılmak artık 500 para (kurmak hâlâ kayıt memurunda 5.000). Ve Highcairn'in üstündeki Greyhorn'un kar başlıkları artık çıplak gri kaya: yamaçların üstünde tuhaf duruyorlardı.", "Unirte a una hermandad a la que te invitó un compañero cuesta ahora 500 monedas (fundarla sigue costando 5.000 en el registro). Y las cumbres nevadas del Greyhorn sobre Highcairn son ahora roca gris desnuda: quedaban raras sobre las laderas.", "Entrar numa irmandade para a qual um companheiro convidou você agora custa 500 moedas (fundar uma ainda custa 5.000 no cartório). E os picos nevados do Greyhorn acima de Highcairn agora são rocha cinza nua: ficavam estranhos sobre as encostas.", "Вступление в братство по приглашению товарища теперь стоит 500 монет (основание по-прежнему 5000 у регистратора). А снежные шапки Грейхорна над Хайкэрном стали голым серым камнем: они странно смотрелись над склонами.", "Вступ до братства за запрошенням товариша тепер коштує 500 монет (заснування й далі 5000 у реєстратора). А снігові шапки Грейгорна над Гайкерном стали голим сірим каменем: вони дивно виглядали над схилами."],
  "Heavier weapons, and armour you can tell apart": ["重厚な武器と、見分けのつく鎧", "더 묵직한 무기, 그리고 구별되는 갑옷", "更厚重的武器，以及辨识度更高的盔甲", "更厚重的武器，以及辨識度更高的盔甲", "Vũ khí nặng nề hơn, và giáp phân biệt được", "Senjata lebih berat, dan zirah yang bisa dibedakan", "อาวุธที่หนักแน่นขึ้น และเกราะที่แยกออกได้", "Daha ağır silahlar ve ayırt edilebilen zırhlar", "Armas más pesadas y armaduras que se distinguen", "Armas mais pesadas e armaduras que dá pra distinguir", "Тяжелее оружие и узнаваемые доспехи", "Важча зброя й упізнавані обладунки"],
  "Maces, flails, battleaxes and war hammers are drawn properly in the hand: a flanged mace head with a boss of gold, a flail's spiked ball on a chain of links, a double-bitted battleaxe with a spike above the haft, and a war hammer's block head with a spike behind. All of them with wrapped grips, capped butts and metal langets.": ["メイス、フレイル、戦斧、ウォーハンマーが手にきちんと描かれるように：金の突起付きのフランジメイスの頭、鎖でつながったフレイルのとげ付き鉄球、柄の上にスパイクのある両刃の戦斧、後ろにスパイクのあるウォーハンマーの角頭。どれも巻きつけた握り、石突き、金属の留め具付きです。", "메이스, 플레일, 전투도끼, 전쟁망치가 손에 제대로 그려집니다: 금 돌기가 달린 날개형 메이스 머리, 사슬에 달린 플레일의 가시 철퇴, 자루 위에 스파이크가 있는 양날 전투도끼, 뒤에 스파이크가 있는 전쟁망치의 각진 머리. 모두 감은 손잡이, 마감한 끝, 금속 덧댐이 있습니다.", "钉锤、连枷、战斧和战锤在手中画得更规范了：带金色凸饰的凸缘锤头，连枷用链环连着的尖刺球，柄上带尖刺的双刃战斧，以及后面带尖刺的方块战锤头。都有缠绕的握柄、包头的柄尾和金属护条。", "釘錘、連枷、戰斧和戰錘在手中畫得更規範了：帶金色凸飾的凸緣錘頭，連枷用鏈環連著的尖刺球，柄上帶尖刺的雙刃戰斧，以及後面帶尖刺的方塊戰錘頭。都有纏繞的握柄、包頭的柄尾和金屬護條。", "Chùy, chùy xích, rìu chiến và búa chiến được vẽ đúng cách trên tay: đầu chùy có cạnh với núm vàng, quả cầu gai của chùy xích trên dây xích, rìu chiến hai lưỡi với mũi nhọn trên cán, và đầu búa chiến khối với mũi nhọn phía sau. Tất cả đều có chuôi quấn, đuôi bịt và nẹp kim loại.", "Gada, cambuk berantai, kapak perang, dan palu perang digambar dengan benar di tangan: kepala gada bersirip dengan tonjolan emas, bola berduri cambuk pada rantai, kapak perang bermata dua dengan paku di atas gagang, dan kepala balok palu perang dengan paku di belakangnya. Semuanya dengan pegangan berbalut, ujung bertutup, dan lapisan logam.", "กระบอง กระบองโซ่ ขวานศึก และค้อนศึกวาดในมือได้ถูกต้อง: หัวกระบองมีครีบพร้อมปุ่มทอง ลูกตุ้มหนามของกระบองโซ่บนโซ่ ขวานศึกสองคมมีหนามเหนือด้าม และหัวค้อนศึกทรงเหลี่ยมมีหนามด้านหลัง ทั้งหมดมีด้ามพันผ้า ปลายด้ามหุ้ม และแถบโลหะ", "Gürzler, dövenler, savaş baltaları ve savaş çekiçleri elde düzgünce çiziliyor: altın topuzlu flanşlı bir gürz başı, halkalı bir zincirde dövenin dikenli topu, sapın üstünde sivri uçlu çift ağızlı bir savaş baltası ve arkasında sivri uçlu blok başlı bir savaş çekici. Hepsinde sarılı kabzalar, kapaklı dipler ve metal şeritler var.", "Mazas, manguales, hachas de batalla y martillos de guerra se dibujan como es debido en la mano: una cabeza de maza con aletas y un botón dorado, la bola con pinchos del mangual en una cadena de eslabones, un hacha de batalla de doble filo con una púa sobre el mango y la cabeza de bloque del martillo de guerra con una púa detrás. Todas con empuñadura envuelta, contera y lengüetas metálicas.", "Maças, manguais, machados de batalha e martelos de guerra são desenhados direito na mão: uma cabeça de maça com flanges e um botão dourado, a bola com espinhos do mangual numa corrente de elos, um machado de batalha de lâmina dupla com um espigão acima do cabo e a cabeça em bloco do martelo de guerra com um espigão atrás. Todos com empunhadura enrolada, ponteira e reforços de metal.", "Булавы, цепы, боевые топоры и боевые молоты как следует нарисованы в руке: шестопёр с золотой шишкой, шипастый шар цепа на цепи из звеньев, двулезвийный боевой топор с шипом над древком и молот с брусчатым бойком и шипом сзади. У всех обмотанная рукоять, окованный конец и металлические лангеты.", "Булави, ціпи, бойові сокири й бойові молоти як слід намальовано в руці: шестопер із золотою шишкою, шипаста куля ціпа на ланцюгу з ланок, дволезова бойова сокира з шипом над держаком і молот із брускуватим бойком і шипом позаду. В усіх обмотане руків'я, окутий кінець і металеві лангети."],
  "Every metal's helm and cuirass has its own make now, not just its colour: blackiron is riveted, ashsteel banded with a knob on the crown, moonsilver wears a crescent, glimmer a gold circlet and sunburst, rarite a plume and a cut gem, frostsilver spikes of ice and chevrons of frost, gloomsteel a spike on the crown and on each pauldron, wyrmscale a fin and scales, hollowsteel a crown of pale points and a hollow ring, cindersteel a crest of flame over ember cracks, and ashenheart a split crest over a burning heart.": ["金属ごとの兜と胸当てに、色だけでなく独自の造りが：ブラックアイアンは鋲打ち、アッシュスチールは帯金と頭頂の突起、ムーンシルバーは三日月、グリマーは金の輪と放射飾り、レアライトは羽根飾りとカットした宝石、frostsilver は氷のとげと霜の山形、gloomsteel は頭頂と両肩当てにスパイク、wyrmscale はひれと鱗、hollowsteel は淡い尖りの冠と虚ろの輪、cindersteel は残り火のひびの上に炎の飾り、ashenheart は燃える心臓の上に割れた飾り。", "모든 금속의 투구와 흉갑이 이제 색만이 아니라 고유한 만듦새를 가집니다: 흑철은 리벳, 잿빛강철은 띠와 정수리 꼭지, 월은은 초승달, 글리머는 금 테와 햇살, 레어라이트는 깃장식과 깎은 보석, frostsilver는 얼음 가시와 서리 갈매기, gloomsteel은 정수리와 양 어깨 갑옷의 가시, wyrmscale은 지느러미와 비늘, hollowsteel은 창백한 뾰족 왕관과 공허의 고리, cindersteel은 불씨 균열 위 불꽃 장식, ashenheart는 불타는 심장 위 갈라진 장식.", "每种金属的头盔和胸甲现在都有自己的造型，而不只是颜色：黑铁铆钉，灰钢带箍、顶上有钮，月银带新月，微光戴金冠饰和日芒，稀晶有羽饰和切割宝石，frostsilver 有冰刺和霜纹，gloomsteel 头顶和两边肩甲都有尖刺，wyrmscale 有鳍和鳞片，hollowsteel 有苍白尖顶的冠和虚空环，cindersteel 在余烬裂纹上有火焰冠饰，ashenheart 在燃烧之心上有分叉冠饰。", "每種金屬的頭盔和胸甲現在都有自己的造型，而不只是顏色：黑鐵鉚釘，灰鋼帶箍、頂上有鈕，月銀帶新月，微光戴金冠飾和日芒，稀晶有羽飾和切割寶石，frostsilver 有冰刺和霜紋，gloomsteel 頭頂和兩邊肩甲都有尖刺，wyrmscale 有鰭和鱗片，hollowsteel 有蒼白尖頂的冠和虛空環，cindersteel 在餘燼裂紋上有火焰冠飾，ashenheart 在燃燒之心上有分叉冠飾。", "Mũ giáp và giáp ngực của mỗi kim loại giờ có kiểu dáng riêng, không chỉ màu: sắt đen tán đinh, thép tro có đai và núm trên đỉnh, bạc trăng mang trăng lưỡi liềm, ánh kim có vòng vàng và tia nắng, rarit có chùm lông và đá quý cắt, frostsilver có gai băng và vạch sương, gloomsteel có gai trên đỉnh và mỗi giáp vai, wyrmscale có vây và vảy, hollowsteel có vương miện nhọn nhạt và vòng hư không, cindersteel có mào lửa trên vết nứt than hồng, và ashenheart có mào chẻ đôi trên trái tim rực cháy.", "Helm dan zirah dada setiap logam kini punya bentuknya sendiri, bukan sekadar warna: besi hitam berpaku keling, baja abu berpita dengan tombol di puncak, perak bulan berhias bulan sabit, kemilau dengan lingkar emas dan pancaran matahari, rarit dengan jambul dan permata potong, frostsilver dengan duri es dan chevron beku, gloomsteel dengan paku di puncak dan di tiap pelindung bahu, wyrmscale dengan sirip dan sisik, hollowsteel dengan mahkota ujung pucat dan cincin hampa, cindersteel dengan jambul api di atas retakan bara, dan ashenheart dengan jambul terbelah di atas jantung yang menyala.", "หมวกเกราะและเกราะอกของแต่ละโลหะตอนนี้มีทรงของตัวเอง ไม่ใช่แค่สี: เหล็กดำตอกหมุด เหล็กเถ้าคาดแถบมีปุ่มบนยอด เงินจันทร์มีจันทร์เสี้ยว ประกายแสงมีวงทองและรัศมีแดด แรไรต์มีพู่และอัญมณีเจีย frostsilver มีหนามน้ำแข็งและลายบั้งน้ำค้างแข็ง gloomsteel มีหนามบนยอดและเกราะไหล่ทั้งสองข้าง wyrmscale มีครีบและเกล็ด hollowsteel มีมงกุฎแหลมสีซีดและวงความว่างเปล่า cindersteel มีหงอนเปลวไฟเหนือรอยแตกถ่านไฟ และ ashenheart มีหงอนแยกเหนือหัวใจที่ลุกไหม้", "Her metalin miğferi ve göğüslüğü artık yalnızca rengiyle değil kendi yapısıyla geliyor: kara demir perçinli, kül çeliği şeritli ve tepesinde topuzlu, ay gümüşünde bir hilal, parıltıda altın bir taç bandı ve güneş ışını, raritte bir sorguç ve kesilmiş bir mücevher, frostsilver'da buz dikenleri ve ayaz şeritleri, gloomsteel'de tepede ve her omuzlukta bir diken, wyrmscale'de bir yüzgeç ve pullar, hollowsteel'de soluk uçlu bir taç ve bir boşluk halkası, cindersteel'de kor çatlakları üstünde alevli bir sorguç ve ashenheart'ta yanan bir kalbin üstünde yarık bir sorguç.", "El yelmo y la coraza de cada metal tienen ahora su propia hechura, no solo su color: el hierro negro va remachado, el acero ceniza con bandas y un botón en la coronilla, la plata lunar lleva una media luna, el destello una diadema dorada y un sol, la rarita un penacho y una gema tallada, el frostsilver púas de hielo y cheurones de escarcha, el gloomsteel una púa en la coronilla y en cada hombrera, el wyrmscale una aleta y escamas, el hollowsteel una corona de puntas pálidas y un anillo hueco, el cindersteel una cresta de llama sobre grietas de brasa y el ashenheart una cresta partida sobre un corazón ardiente.", "O elmo e a couraça de cada metal agora têm feitio próprio, não só a cor: o ferro negro é rebitado, o aço cinzento tem faixas e um botão no topo, a prata lunar usa uma lua crescente, o lampejo um diadema dourado e um sol, a rarita um penacho e uma gema lapidada, o frostsilver espinhos de gelo e divisas de geada, o gloomsteel um espigão no topo e em cada ombreira, o wyrmscale uma barbatana e escamas, o hollowsteel uma coroa de pontas pálidas e um anel oco, o cindersteel uma crista de chama sobre rachaduras de brasa e o ashenheart uma crista partida sobre um coração em chamas.", "Шлем и кираса каждого металла теперь отличаются выделкой, а не только цветом: чёрное железо в заклёпках, пепельная сталь в обручах с шишкой на макушке, лунное серебро с полумесяцем, мерцалит с золотым обручем и солнцем, рарит с плюмажем и огранённым камнем, frostsilver с ледяными шипами и морозными шевронами, gloomsteel с шипом на макушке и на каждом наплечнике, wyrmscale с плавником и чешуёй, hollowsteel с короной бледных зубцов и пустотным кольцом, cindersteel с огненным гребнем над тлеющими трещинами, а ashenheart с расщеплённым гребнем над пылающим сердцем.", "Шолом і кіраса кожного металу тепер вирізняються виробкою, а не лише кольором: чорне залізо в заклепках, попеляста сталь в обручах із шишкою на маківці, місячне срібло з півмісяцем, мерехтит із золотим обручем і сонцем, рарит із плюмажем і огранованим каменем, frostsilver із крижаними шипами й морозними шевронами, gloomsteel із шипом на маківці й на кожному наплічнику, wyrmscale із плавцем і лускою, hollowsteel із короною блідих зубців і порожнечним кільцем, cindersteel із вогняним гребенем над жевріючими тріщинами, а ashenheart із розщепленим гребенем над палаючим серцем."],
  "A finer aegis, and shields that hang under your cape": ["より立派なイージスと、マントの下に掛かる盾", "더 멋진 아이기스, 그리고 망토 아래 걸리는 방패", "更精致的神盾，以及挂在披风下的盾牌", "更精緻的神盾，以及掛在披風下的盾牌", "Khiên thánh đẹp hơn, và khiên treo dưới áo choàng", "Aegis yang lebih indah, dan perisai yang tergantung di bawah jubah", "อีจิสที่สวยขึ้น และโล่ที่ห้อยใต้ผ้าคลุม", "Daha güzel bir egis ve pelerinin altında asılı kalkanlar", "Una égida más fina y escudos que cuelgan bajo la capa", "Uma égide mais caprichada e escudos que ficam sob a capa", "Изящнее эгида и щиты, висящие под плащом", "Вишуканіша егіда й щити, що висять під плащем"],
  "The aegis is drawn properly: a broad tower shield with a bevelled, riveted rim, a band across its lower third, and the sun of its blessing, a ringed gold disc with a pale heart and eight rays.": ["イージスがきちんと描かれるように：面取りと鋲打ちの縁を持つ幅広のタワーシールドで、下3分の1に帯が渡り、祝福の太陽（淡い中心と8本の光線を持つ輪付きの金の円盤）が描かれています。", "아이기스가 제대로 그려집니다: 비스듬히 깎고 리벳을 박은 테두리의 넓은 탑 방패에, 아래 3분의 1에 띠가 가로지르고, 축복의 태양(창백한 중심과 여덟 줄기 빛살이 있는 고리 두른 금 원반)이 있습니다.", "神盾画得更讲究了：一面宽大的塔盾，边缘有斜面和铆钉，下三分之一处横着一道箍，还有它的祝福之日，一个带环的金盘，有苍白的中心和八道光芒。", "神盾畫得更講究了：一面寬大的塔盾，邊緣有斜面和鉚釘，下三分之一處橫著一道箍，還有它的祝福之日，一個帶環的金盤，有蒼白的中心和八道光芒。", "Khiên thánh được vẽ đúng cách: khiên tháp rộng với viền vát cạnh tán đinh, một dải ngang một phần ba phía dưới, và mặt trời ban phước của nó, đĩa vàng có vòng với tâm nhạt và tám tia.", "Aegis digambar dengan benar: perisai menara lebar dengan pinggiran miring berpaku keling, pita melintang di sepertiga bawahnya, dan matahari berkatnya, cakram emas bercincin dengan inti pucat dan delapan sinar.", "อีจิสวาดได้ถูกต้อง: โล่หอคอยกว้างมีขอบลบมุมตอกหมุด แถบพาดหนึ่งในสามส่วนล่าง และดวงอาทิตย์แห่งพร จานทองมีวงพร้อมใจกลางสีซีดและแปดรัศมี", "Egis düzgünce çiziliyor: eğimli, perçinli kenarlı geniş bir kule kalkanı, alt üçte birinde bir şerit ve kutsamasının güneşi, soluk bir merkezi ve sekiz ışını olan halkalı altın bir disk.", "La égida se dibuja como es debido: un amplio escudo de torre con borde biselado y remachado, una banda en su tercio inferior y el sol de su bendición, un disco dorado anillado con corazón pálido y ocho rayos.", "A égide é desenhada direito: um escudo-torre largo com borda chanfrada e rebitada, uma faixa no terço inferior e o sol da sua bênção, um disco dourado com anel, centro claro e oito raios.", "Эгида нарисована как следует: широкий ростовой щит со скошенной клёпаной кромкой, полосой поперёк нижней трети и солнцем благословения — золотым диском с кольцом, бледной сердцевиной и восемью лучами.", "Егіду намальовано як слід: широкий ростовий щит зі скошеною клепаною крайкою, смугою впоперек нижньої третини й сонцем благословення — золотим диском із кільцем, блідою серцевиною й вісьмома променями."],
  "Seen from behind, a shield hangs under your cape instead of sitting on top of it: the cape falls over most of it and its wooden back peeks out beside the cape's edge. Without a cape you see the whole back, planks and straps.": ["後ろから見ると、盾はマントの上ではなく下に掛かります：マントがほとんどを覆い、木の裏面がマントの端の横からのぞきます。マントがなければ裏面全体、板とベルトが見えます。", "뒤에서 보면 방패가 망토 위가 아니라 아래에 걸립니다: 망토가 대부분을 덮고, 나무 뒷면이 망토 가장자리 옆으로 살짝 보입니다. 망토가 없으면 판자와 끈까지 뒷면 전체가 보입니다.", "从背后看，盾牌挂在披风下面而不是压在上面：披风盖住大部分，木制的盾背从披风边缘旁露出来。没有披风时，你会看到整个盾背、木板和背带。", "從背後看，盾牌掛在披風下面而不是壓在上面：披風蓋住大部分，木製的盾背從披風邊緣旁露出來。沒有披風時，你會看到整個盾背、木板和背帶。", "Nhìn từ phía sau, khiên treo dưới áo choàng thay vì nằm đè lên: áo choàng phủ gần hết và mặt gỗ phía sau ló ra cạnh mép áo choàng. Không có áo choàng thì thấy cả mặt sau, ván gỗ và dây đai.", "Dilihat dari belakang, perisai tergantung di bawah jubah alih-alih di atasnya: jubah menutupi sebagian besar dan punggung kayunya mengintip di samping tepi jubah. Tanpa jubah kau melihat seluruh punggungnya, papan dan talinya.", "มองจากด้านหลัง โล่ห้อยอยู่ใต้ผ้าคลุมแทนที่จะทับอยู่ข้างบน: ผ้าคลุมปิดเกือบทั้งหมด และหลังโล่ไม้โผล่ออกมาข้างขอบผ้าคลุม ถ้าไม่ใส่ผ้าคลุมจะเห็นด้านหลังทั้งหมด ทั้งแผ่นไม้และสายรัด", "Arkadan bakınca kalkan pelerininin üstünde durmak yerine altında asılı: pelerin çoğunu örtüyor ve ahşap arkası pelerinin kenarının yanından görünüyor. Pelerin yoksa tüm arkasını, tahtalarını ve kayışlarını görürsün.", "Visto desde detrás, el escudo cuelga bajo la capa en vez de ir encima: la capa cae sobre casi todo y su dorso de madera asoma junto al borde de la capa. Sin capa ves todo el dorso, tablas y correas.", "Visto de trás, o escudo fica sob a capa em vez de por cima: a capa cai sobre quase todo ele e o verso de madeira aparece ao lado da borda da capa. Sem capa você vê o verso inteiro, tábuas e correias.", "Если смотреть сзади, щит висит под плащом, а не поверх: плащ закрывает большую часть, а деревянная оборотная сторона выглядывает у края плаща. Без плаща видна вся оборотная сторона — доски и ремни.", "Якщо дивитися ззаду, щит висить під плащем, а не поверх: плащ закриває більшу частину, а дерев'яний зворотний бік виглядає біля краю плаща. Без плаща видно весь зворотний бік — дошки й ремені."],
  "A smoother, faster Realm, and water barrels that work": ["よりなめらかで速いレルムと、使える水樽", "더 매끄럽고 빠른 렐름, 그리고 제대로 쓰이는 물통", "更流畅更快的王国，以及能用的水桶", "更流暢更快的王國，以及能用的水桶", "Vương quốc mượt và nhanh hơn, và thùng nước dùng được", "Realm yang lebih mulus dan cepat, dan tong air yang berfungsi", "อาณาจักรที่ลื่นและเร็วขึ้น และถังน้ำที่ใช้ได้", "Daha akıcı, daha hızlı bir Diyar ve çalışan su fıçıları", "Un Reino más fluido y rápido, y barriles de agua que funcionan", "Um Reino mais suave e rápido, e barris de água que funcionam", "Плавнее и быстрее Королевство и работающие бочки с водой", "Плавніше й швидше Королівство та бочки з водою, що працюють"],
  "The Realm draws about twice as fast on High graphics. The ground is painted once and slid under the camera as you walk instead of being redrawn every frame (only the water and lava move on it), scenery lays its own sprites again for its shadow and its light instead of drawing itself three times over, walls, roofs, cliffs and ridges are lit by their outlines, and the light field is worked out every other frame. Dense forests and towns that ran at twenty-odd frames a second now run at forty to sixty.": ["高画質でのレルムの描画が約2倍速くなりました。地面は毎フレーム描き直すのではなく一度描いて、歩くとカメラの下でスライドさせます（動くのは水と溶岩だけ）。景物は自分自身を3回描く代わりにスプライトを影と光に使い回し、壁、屋根、崖、尾根は輪郭で照らされ、光の分布は1フレームおきに計算されます。毎秒20フレーム台だった深い森や町は、40〜60フレームで動くようになりました。", "그래픽 높음에서 렐름이 약 두 배 빨리 그려집니다. 바닥은 매 프레임 다시 그리지 않고 한 번 그려서 걸을 때 카메라 아래로 밀어 줍니다(그 위에서 움직이는 건 물과 용암뿐). 풍경은 자신을 세 번 그리는 대신 스프라이트를 그림자와 빛에 다시 쓰고, 벽, 지붕, 절벽, 능선은 외곽선으로 조명되며, 빛 분포는 한 프레임 걸러 계산합니다. 초당 20여 프레임이던 울창한 숲과 마을이 이제 40~60프레임으로 돌아갑니다.", "高画质下王国的绘制速度大约提升了一倍。地面只绘制一次，随你行走在镜头下滑动，而不是每帧重绘（只有水和岩浆在上面动）；景物重新为阴影和光照复用自己的精灵图，而不是把自己画三遍；墙壁、屋顶、悬崖和山脊按轮廓打光；光场每隔一帧计算一次。原本每秒二十来帧的茂密森林和城镇，现在能跑四十到六十帧。", "高畫質下王國的繪製速度大約提升了一倍。地面只繪製一次，隨你行走在鏡頭下滑動，而不是每幀重繪（只有水和岩漿在上面動）；景物重新為陰影和光照複用自己的精靈圖，而不是把自己畫三遍；牆壁、屋頂、懸崖和山脊按輪廓打光；光場每隔一幀計算一次。原本每秒二十來幀的茂密森林和城鎮，現在能跑四十到六十幀。", "Vương quốc vẽ nhanh gấp khoảng hai lần ở đồ họa Cao. Mặt đất được vẽ một lần và trượt dưới máy quay khi bạn đi thay vì vẽ lại mỗi khung hình (chỉ nước và dung nham chuyển động trên đó), cảnh vật dùng lại sprite của chính nó cho bóng và ánh sáng thay vì tự vẽ ba lần, tường, mái, vách đá và sống núi được chiếu sáng theo đường viền, và trường ánh sáng được tính cách một khung hình. Rừng rậm và thị trấn trước chạy hai mươi mấy khung hình mỗi giây giờ chạy bốn mươi đến sáu mươi.", "Realm digambar sekitar dua kali lebih cepat di grafis Tinggi. Tanah dilukis sekali dan digeser di bawah kamera saat kau berjalan alih-alih digambar ulang setiap bingkai (hanya air dan lava yang bergerak di atasnya), pemandangan memakai sprite-nya sendiri lagi untuk bayangan dan cahayanya alih-alih menggambar diri tiga kali, dinding, atap, tebing, dan punggung bukit diterangi dari garis tepinya, dan medan cahaya dihitung setiap dua bingkai. Hutan lebat dan kota yang dulu berjalan dua puluhan bingkai per detik kini empat puluh hingga enam puluh.", "อาณาจักรวาดเร็วขึ้นประมาณสองเท่าในกราฟิกสูง พื้นวาดครั้งเดียวแล้วเลื่อนใต้กล้องขณะเดินแทนที่จะวาดใหม่ทุกเฟรม (มีแค่น้ำและลาวาที่ขยับอยู่บนนั้น) ฉากใช้สไปรต์ของตัวเองซ้ำสำหรับเงาและแสงแทนที่จะวาดตัวเองสามรอบ กำแพง หลังคา หน้าผา และสันเขาได้แสงตามโครงร่าง และคำนวณสนามแสงเว้นเฟรม ป่าทึบและเมืองที่เคยวิ่งยี่สิบกว่าเฟรมต่อวินาทีตอนนี้วิ่งสี่สิบถึงหกสิบ", "Diyar Yüksek grafikte yaklaşık iki kat hızlı çiziliyor. Zemin her karede yeniden çizilmek yerine bir kez boyanıp sen yürürken kameranın altında kaydırılıyor (üstünde yalnızca su ve lav hareket ediyor), manzara kendini üç kez çizmek yerine gölgesi ve ışığı için kendi sprite'larını yeniden kullanıyor, duvarlar, çatılar, uçurumlar ve sırtlar hatlarından aydınlatılıyor ve ışık alanı her iki karede bir hesaplanıyor. Saniyede yirmi küsur karede çalışan sık ormanlar ve kasabalar artık kırk ile altmış arası.", "El Reino se dibuja unas dos veces más rápido en gráficos Altos. El suelo se pinta una vez y se desliza bajo la cámara al caminar en vez de redibujarse cada fotograma (solo el agua y la lava se mueven sobre él), el decorado vuelve a usar sus propios sprites para su sombra y su luz en vez de dibujarse tres veces, muros, tejados, acantilados y crestas se iluminan por su contorno, y el campo de luz se calcula un fotograma sí y otro no. Bosques densos y pueblos que iban a veintitantos fotogramas por segundo van ahora a entre cuarenta y sesenta.", "O Reino desenha cerca de duas vezes mais rápido nos gráficos Altos. O chão é pintado uma vez e deslizado sob a câmera enquanto você anda em vez de ser redesenhado a cada quadro (só a água e a lava se movem nele), o cenário volta a usar os próprios sprites para sombra e luz em vez de se desenhar três vezes, paredes, telhados, penhascos e cristas são iluminados pelos contornos, e o campo de luz é calculado a cada dois quadros. Florestas densas e cidades que rodavam a vinte e poucos quadros por segundo agora rodam a quarenta a sessenta.", "На высокой графике Королевство рисуется примерно вдвое быстрее. Земля рисуется один раз и скользит под камерой, пока вы идёте, а не перерисовывается каждый кадр (по ней движутся только вода и лава); декорации снова используют свои спрайты для тени и света, а не рисуют себя трижды; стены, крыши, скалы и гребни освещаются по контуру, а поле света считается через кадр. Густые леса и города, где было двадцать с небольшим кадров в секунду, теперь идут на сорока–шестидесяти.", "На високій графіці Королівство малюється приблизно вдвічі швидше. Земля малюється один раз і ковзає під камерою, поки ви йдете, а не перемальовується щокадру (по ній рухаються лише вода й лава); декорації знову використовують свої спрайти для тіні й світла, а не малюють себе тричі; стіни, дахи, скелі й гребені освітлюються за контуром, а поле світла рахується через кадр. Густі ліси й міста, де було двадцять із чимось кадрів на секунду, тепер ідуть на сорока–шістдесяти."],
  "Every water barrel in every village is a water barrel: right-click it to fill your vials. Friendhollow, Fernwick, Emberforge, Highcairn, Gravesend, Saltmarrow and the rest all have one by the well, the inn or the apothecary.": ["どの村の水樽もちゃんと水樽として使えます：右クリックで小瓶を満たせます。フレンドホロウ、ファーンウィック、エンバーフォージ、ハイケアン、グレイヴセンド、ソルトマロウなど、どこにも井戸か宿か薬屋のそばに1つあります。", "모든 마을의 물통이 진짜 물통이 되었습니다: 우클릭으로 약병을 채우세요. 프렌드할로우, 펀윅, 엠버포지, 하이케언, 그레이브센드, 솔트매로 등 모두 우물, 여관, 약방 옆에 하나씩 있습니다.", "每个村庄的每个水桶都能当水桶用了：右键即可装满药瓶。友谷、蕨村、烬炉、高冢、墓终、盐髓港等地，井边、旅店或药铺旁都有一个。", "每個村莊的每個水桶都能當水桶用了：右鍵即可裝滿藥瓶。友谷、蕨村、燼爐、高塚、墓終、鹽髓港等地，井邊、旅店或藥鋪旁都有一個。", "Mọi thùng nước ở mọi làng đều là thùng nước thật: nhấp chuột phải để đổ đầy lọ. Friendhollow, Fernwick, Emberforge, Highcairn, Gravesend, Saltmarrow và những nơi khác đều có một cái cạnh giếng, quán trọ hoặc tiệm bào chế.", "Setiap tong air di setiap desa adalah tong air sungguhan: klik kanan untuk mengisi botolmu. Friendhollow, Fernwick, Emberforge, Highcairn, Gravesend, Saltmarrow, dan lainnya punya satu di dekat sumur, penginapan, atau peracik obat.", "ถังน้ำทุกถังในทุกหมู่บ้านใช้เป็นถังน้ำได้จริง: คลิกขวาเพื่อเติมขวด เฟรนด์ฮอลโลว์ เฟิร์นวิก เอมเบอร์ฟอร์จ ไฮแคร์น เกรฟเซนด์ ซอลต์แมร์โรว์ และที่อื่นๆ มีถังหนึ่งข้างบ่อน้ำ โรงเตี๊ยม หรือร้านปรุงยา", "Her köydeki her su fıçısı gerçekten bir su fıçısı: şişelerini doldurmak için sağ tıkla. Friendhollow, Fernwick, Emberforge, Highcairn, Gravesend, Saltmarrow ve diğerlerinin hepsinde kuyunun, hanın ya da eczacının yanında bir tane var.", "Cada barril de agua de cada pueblo es un barril de agua: haz clic derecho para llenar tus viales. Friendhollow, Fernwick, Emberforge, Highcairn, Gravesend, Saltmarrow y los demás tienen uno junto al pozo, la posada o la botica.", "Todo barril de água de toda vila é um barril de água: clique direito para encher seus frascos. Friendhollow, Fernwick, Emberforge, Highcairn, Gravesend, Saltmarrow e o resto têm um perto do poço, da estalagem ou do boticário.", "Каждая бочка с водой в каждой деревне — настоящая бочка: кликните правой кнопкой, чтобы наполнить склянки. Во Френдхоллоу, Фернвике, Эмберфордже, Хайкэрне, Грейвсенде, Солтмэрроу и остальных она стоит у колодца, трактира или аптеки.", "Кожна бочка з водою в кожному селі — справжня бочка: клацніть правою кнопкою, щоб наповнити флакони. У Френдголлоу, Фернвіку, Емберфорджі, Гайкерні, Грейвсенді, Солтмерроу й решті вона стоїть біля криниці, корчми чи аптеки."],
  "Crypt bones, and the Order's armour for everyone": ["地下墓所の骨と、みんなのための騎士団の鎧", "지하묘지 뼈, 그리고 모두를 위한 기사단 갑옷", "墓穴骨头，以及人人可得的骑士团盔甲", "墓穴骨頭，以及人人可得的騎士團盔甲", "Xương hầm mộ, và giáp của Dòng cho mọi người", "Tulang kripta, dan zirah Ordo untuk semua", "กระดูกห้องใต้ดิน และเกราะของภาคีสำหรับทุกคน", "Mahzen kemikleri ve herkes için Tarikat zırhı", "Huesos de cripta y la armadura de la Orden para todos", "Ossos de cripta e a armadura da Ordem para todos", "Кости из склепа и доспехи Ордена для всех", "Кістки зі склепу й обладунки Ордену для всіх"],
  "Crypt skeletons drop crypt bones: grey and cracked, worth twice a plain bone's Faith and a little over half a large one's (9 Faith buried, more on an altar).": ["地下墓所の骸骨が地下墓所の骨を落とすように：灰色でひび割れ、信仰は普通の骨の2倍、大きな骨の半分強（埋めると信仰9、祭壇ならさらに多く）。", "지하묘지 해골이 지하묘지 뼈를 떨어뜨립니다: 회색에 금이 갔고, 신앙은 보통 뼈의 두 배, 큰 뼈의 절반 조금 넘게(묻으면 신앙 9, 제단에선 더 많이).", "墓穴骷髅会掉落墓穴骨头：灰色带裂纹，信仰经验是普通骨头的两倍，略多于大骨头的一半（掩埋 9 点信仰，在祭坛上更多）。", "墓穴骷髏會掉落墓穴骨頭：灰色帶裂紋，信仰經驗是普通骨頭的兩倍，略多於大骨頭的一半（掩埋 9 點信仰，在祭壇上更多）。", "Bộ xương hầm mộ rơi xương hầm mộ: xám và nứt nẻ, giá trị Đức tin gấp đôi xương thường và hơn một nửa xương lớn một chút (chôn được 9 Đức tin, trên bàn thờ nhiều hơn).", "Kerangka kripta menjatuhkan tulang kripta: abu-abu dan retak, bernilai dua kali Iman tulang biasa dan sedikit lebih dari setengah tulang besar (9 Iman dikubur, lebih di altar).", "โครงกระดูกห้องใต้ดินดรอปกระดูกห้องใต้ดิน: สีเทาแตกร้าว มีค่าศรัทธาสองเท่าของกระดูกธรรมดาและเกินครึ่งของกระดูกใหญ่เล็กน้อย (ฝังได้ศรัทธา 9 บนแท่นบูชาได้มากกว่า)", "Mahzen iskeletleri mahzen kemikleri düşürüyor: gri ve çatlak, sıradan bir kemiğin iki katı, büyük bir kemiğin yarısından biraz fazla İnanç değerinde (gömülünce 9 İnanç, sunakta daha fazla).", "Los esqueletos de cripta sueltan huesos de cripta: grises y agrietados, valen el doble de Fe que un hueso normal y algo más de la mitad que uno grande (9 de Fe enterrados, más en un altar).", "Os esqueletos de cripta soltam ossos de cripta: cinzentos e rachados, valem o dobro da Fé de um osso comum e um pouco mais da metade de um grande (9 de Fé enterrados, mais num altar).", "Скелеты склепа роняют кости из склепа: серые и треснувшие, стоят вдвое больше Веры, чем обычная кость, и чуть больше половины большой (9 Веры при погребении, больше на алтаре).", "Скелети склепу впускають кістки зі склепу: сірі й тріснуті, варті вдвічі більше Віри, ніж звичайна кістка, і трохи більше половини великої (9 Віри за поховання, більше на вівтарі)."],
  "The aegis is a tower shield now, square at the foot, so the Realm has three shield shapes: the kite, the round shield and the aegis.": ["イージスは下端が四角いタワーシールドになり、レルムの盾はカイト、丸盾、イージスの3つの形になりました。", "아이기스가 이제 아래가 각진 탑 방패라서, 렐름의 방패 모양은 연 방패, 원형 방패, 아이기스 셋입니다.", "神盾现在是底部方正的塔盾，所以王国有三种盾形：鸢盾、圆盾和神盾。", "神盾現在是底部方正的塔盾，所以王國有三種盾形：鳶盾、圓盾和神盾。", "Khiên thánh giờ là khiên tháp, vuông ở chân, nên Vương quốc có ba hình khiên: khiên diều, khiên tròn và khiên thánh.", "Aegis kini perisai menara, persegi di bawahnya, jadi Realm punya tiga bentuk perisai: layang, bundar, dan aegis.", "อีจิสตอนนี้เป็นโล่หอคอยฐานเหลี่ยม อาณาจักรจึงมีโล่สามทรง: โล่ว่าว โล่กลม และอีจิส", "Egis artık dibi kare bir kule kalkanı, böylece Diyar'da üç kalkan şekli var: uçurtma, yuvarlak kalkan ve egis.", "La égida es ahora un escudo de torre, cuadrado por abajo, así que el Reino tiene tres formas de escudo: el de cometa, el redondo y la égida.", "A égide agora é um escudo-torre, reto embaixo, então o Reino tem três formatos de escudo: o de pipa, o redondo e a égide.", "Эгида теперь ростовой щит с квадратным низом, так что в Королевстве три формы щитов: каплевидный, круглый и эгида.", "Егіда тепер ростовий щит із квадратним низом, тож у Королівстві три форми щитів: мигдалеподібний, круглий і егіда."],
  "The Order Armoury at Dawnhold sells two sets below Dawnplate now. The Acolyte's vestments (hood, vestment, leggings, gloves, sandals: cloth, cheap, Faith 10) once you've kept the Dawn Vigil, and the Vigil's mail (helm, hauberk, greaves, gauntlets, boots, shield: Defence 30 and Faith 30) once the Dawnstone is home. Both carry a faith bonus. Three pieces of either give you a style of your own on the Presence profile.": ["ドーンホールドの Order Armoury では、Dawnplate より下の装備一式を2つ売るようになりました。「夜明けの寝ずの番」を終えると侍祭の祭服（フード、祭服、レギンス、手袋、サンダル：布製、安価、信仰10）、暁石が戻ると Vigil's mail（兜、鎖帷子、すね当て、籠手、ブーツ、盾：防御30と信仰30）。どちらも信仰ボーナス付き。どちらか3部位で名声のプロフィールに独自のスタイルがつきます。", "돈홀드의 Order Armoury가 이제 Dawnplate 아래의 세트 둘을 팝니다. '새벽의 철야'를 마치면 시종의 제의(두건, 제의, 레깅스, 장갑, 샌들: 천, 저렴, 신앙 10), 여명석이 돌아오면 Vigil's mail(투구, 사슬 갑옷, 정강이받이, 건틀릿, 장화, 방패: 방어 30과 신앙 30). 둘 다 신앙 보너스가 있습니다. 어느 쪽이든 세 부위면 명성 프로필에 나만의 스타일이 생깁니다.", "晨堡的 Order Armoury 现在出售两套低于 Dawnplate 的套装。完成「黎明守夜」后可买侍僧法衣（兜帽、法衣、绑腿、手套、凉鞋：布制、便宜、信仰 10），晨曦石归位后可买 Vigil's mail（头盔、锁子甲、护胫、护手、靴子、盾牌：防御 30 和信仰 30）。两套都带信仰加成。任一套集齐三件，就会在声望档案中获得专属风格。", "晨堡的 Order Armoury 現在出售兩套低於 Dawnplate 的套裝。完成「黎明守夜」後可買侍僧法衣（兜帽、法衣、綁腿、手套、涼鞋：布製、便宜、信仰 10），晨曦石歸位後可買 Vigil's mail（頭盔、鎖子甲、護脛、護手、靴子、盾牌：防禦 30 和信仰 30）。兩套都帶信仰加成。任一套集齊三件，就會在聲望檔案中獲得專屬風格。", "Order Armoury ở Dawnhold giờ bán hai bộ dưới Dawnplate. Lễ phục thầy giúp lễ (mũ trùm, lễ phục, xà cạp, găng tay, dép: vải, rẻ, Đức tin 10) sau khi bạn đã Canh thức Bình minh, và Vigil's mail (mũ giáp, áo giáp xích, giáp chân, găng giáp, ủng, khiên: Phòng thủ 30 và Đức tin 30) sau khi Đá bình minh về chỗ. Cả hai có thưởng đức tin. Ba món của bộ nào cũng cho bạn một phong cách riêng trên hồ sơ Danh tiếng.", "Order Armoury di Dawnhold kini menjual dua set di bawah Dawnplate. Jubah pembantu imam (tudung, jubah, celana ketat, sarung tangan, sandal: kain, murah, Iman 10) setelah kau menjalani Jaga Fajar, dan Vigil's mail (helm, baju zirah rantai, pelindung kaki, sarung tangan zirah, sepatu bot, perisai: Pertahanan 30 dan Iman 30) setelah Batu fajar kembali. Keduanya punya bonus iman. Tiga bagian dari salah satunya memberimu gaya sendiri di profil Kehadiran.", "Order Armoury ที่ดอว์นโฮลด์ตอนนี้ขายสองชุดที่ต่ำกว่า Dawnplate เสื้อพิธีผู้ช่วยนักบวช (ฮู้ด เสื้อพิธี กางเกงรัด ถุงมือ รองเท้าแตะ: ผ้า ราคาถูก ศรัทธา 10) เมื่อคุณเฝ้ารุ่งอรุณแล้ว และ Vigil's mail (หมวกเกราะ เสื้อเกราะโซ่ สนับแข้ง ถุงมือเกราะ รองเท้าบูต โล่: ป้องกัน 30 และศรัทธา 30) เมื่อหินรุ่งอรุณกลับที่ ทั้งสองมีโบนัสศรัทธา สามชิ้นของชุดใดชุดหนึ่งให้สไตล์ของคุณเองบนโปรไฟล์ชื่อเสียง", "Dawnhold'daki Order Armoury artık Dawnplate'in altında iki takım satıyor. Şafak Nöbeti'ni tuttuktan sonra Yardımcı rahip cüppesi (kapüşon, cüppe, tozluk, eldiven, sandalet: kumaş, ucuz, İnanç 10) ve Şafak taşı yerine dönünce Vigil's mail (miğfer, zincir zırh, dizlik, eldiven, bot, kalkan: Savunma 30 ve İnanç 30). İkisinde de inanç bonusu var. Herhangi birinin üç parçası sana Şöhret profilinde kendine ait bir tarz veriyor.", "La Order Armoury de Dawnhold vende ahora dos conjuntos por debajo de la Dawnplate. La Vestidura de acólito (capucha, vestidura, mallas, guantes, sandalias: tela, barata, Fe 10) una vez hecha La vigilia del Alba, y la Vigil's mail (yelmo, cota, grebas, guanteletes, botas, escudo: Defensa 30 y Fe 30) una vez la Piedra del alba vuelve a casa. Ambos llevan bonus de fe. Tres piezas de cualquiera te dan un estilo propio en el perfil de Presencia.", "A Order Armoury em Dawnhold agora vende dois conjuntos abaixo da Dawnplate. A Vestimenta de acólito (capuz, veste, perneiras, luvas, sandálias: tecido, barata, Fé 10) depois que você fez A Vigília da Aurora, e a Vigil's mail (elmo, cota, grevas, manoplas, botas, escudo: Defesa 30 e Fé 30) depois que a Pedra-da-aurora volta para casa. Os dois têm bônus de fé. Três peças de qualquer um dão um estilo próprio no perfil de Presença.", "Order Armoury в Даунхолде теперь продаёт два комплекта ниже Dawnplate: облачение послушника (капюшон, облачение, поножи, перчатки, сандалии: ткань, дёшево, Вера 10) — после «Бдения Рассвета», и Vigil's mail (шлем, кольчуга, поножи, латные перчатки, сапоги, щит: Защита 30 и Вера 30) — когда Камень зари вернётся на место. У обоих бонус веры. Три предмета любого из них дают собственный стиль в профиле Славы.", "Order Armoury в Даунголді тепер продає два комплекти нижче Dawnplate: облачення прислужника (каптур, облачення, наголінники, рукавички, сандалі: тканина, дешево, Віра 10) — після «Чування Світанку», і Vigil's mail (шолом, кольчуга, наголінники, латні рукавиці, чоботи, щит: Захист 30 і Віра 30) — коли Камінь світанку повернеться на місце. В обох бонус віри. Три предмети будь-якого з них дають власний стиль у профілі Слави."],
};
